import{_ as o,o as i,c as n,ag as c}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-31（生物医学 / 比较基因组 · 全脊椎动物单细胞图谱）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-31-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-31-biomed.md"}'),t={name:"topics/biomedicine/science-daily-2026-10-31-biomed.md"};function r(s,e,d,l,a,g){return i(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-10-31-生物医学-比较基因组-·-全脊椎动物单细胞图谱" tabindex="-1">科学日报 · 2026-10-31（生物医学 / 比较基因组 · 全脊椎动物单细胞图谱） <a class="header-anchor" href="#科学日报-·-2026-10-31-生物医学-比较基因组-·-全脊椎动物单细胞图谱" aria-label="Permalink to &quot;科学日报 · 2026-10-31（生物医学 / 比较基因组 · 全脊椎动物单细胞图谱）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-31.md</code> — 第50期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-31-生物医学-·-1-1-一整个脊椎动物的单细胞图谱——透明小鱼-danionella-cerebrum" tabindex="-1">科学日报 2026-10-31（生物医学 · 1/1）：一整个脊椎动物的单细胞图谱——透明小鱼 Danionella cerebrum <a class="header-anchor" href="#科学日报-2026-10-31-生物医学-·-1-1-一整个脊椎动物的单细胞图谱——透明小鱼-danionella-cerebrum" aria-label="Permalink to &quot;科学日报 2026-10-31（生物医学 · 1/1）：一整个脊椎动物的单细胞图谱——透明小鱼 Danionella cerebrum&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-31.md</code> ｜ DOI: 10.1126/science.aeg1125 ｜ Science (2026)</p></blockquote><ul><li>问题：一个<strong>完整脊椎动物的细胞类型转录组图谱</strong>能推动对动物细胞类型组成、组织与演化的理解；但要在一只动物身上做<strong>全身、单细胞分辨率</strong>的图谱，通常受制于<strong>体积、不透明与不可再生</strong>。</li><li>方法：选择<strong>微小、透明、可再生</strong>的硬骨鱼 <em><strong>Danionella cerebrum</strong></em>（把「全脊椎动物单细胞实验」变成可行），对其成体全身做<strong>按区域分层的单细胞 RNA 测序</strong>，并用<strong>空间转录组</strong>以单细胞分辨率绘制细胞类型与基因表达图。</li><li>结果（实测）： <ul><li>按区域基因表达特征<strong>划分出空间上截然不同的神经细胞类型</strong>；</li><li>全身图谱揭示了<strong>携带「成体分子位置记忆」的细胞类型</strong>；</li><li>发现<strong>幼态延续（paedomorphic）特征</strong>；</li><li>在<strong>成体结缔组织</strong>中发现<strong>保守的身体分区与附肢特化程序</strong>；</li><li>比较分析识别出<strong>保守的神经细胞类型</strong>；再生数据集揭示<strong>端脑再生过程中的表达动态</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>neuroscience</code>）： <ol><li><strong>「把『整只动物』变成可扫描单位」＝先选对模式生物</strong> —— 不是把图谱技术变强，而是<strong>换一只足够小、透明、可再生的鱼</strong>，让「全身单细胞」从「不可能」变成「一次实验」。判据：<strong>当某个测量受制于样本属性（太大/不透明/不可再生）时，先问有没有一个属性恰好合适的模式生物，而不是硬攻测量技术。</strong></li><li><strong>「成体里藏着发育期的位置记忆」</strong> —— 发现携带<strong>成体分子位置记忆</strong>的细胞类型、以及<strong>幼态延续</strong>，说明<strong>成体组织并非完全抹掉发育坐标</strong>。判据：<strong>在发育/再生问题里，先查成体细胞是否保留了位置/发育期的分子坐标，而不是假设它们被抹平（去分化）。</strong></li><li><strong>一句话定位</strong>：给 <code>biomedicine</code> 的「细胞图谱」主线补一个<strong>全脊椎动物尺度</strong>的参照资源，并与 10-30「肾癌肿瘤组装体」互补（一个测正常全身、一个建病理微环境）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ <code>topics/neuroscience/index.md</code> ｜ 第50期 科学板块</p></blockquote><p>关键词：科学日报第50期、Danionella cerebrum、全脊椎动物单细胞图谱、透明小鱼、区域分层 scRNA-seq、空间转录组、空间上截然不同的神经细胞类型、成体分子位置记忆、幼态延续 paedomorphic、保守身体分区、附肢特化程序、结缔组织、保守神经细胞类型、端脑再生、模式生物选择、发育坐标保留</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-30-biomed.md</code>（肿瘤组装体 / 真核起源）、<code>topics/biomedicine/science-daily-2026-10-29-biomed.md</code>、<code>topics/neuroscience/index.md</code>、<code>topics/neuroscience/science-daily-2026-10-30-neuro.md</code></p>',10)])])}const b=o(t,[["render",r]]);export{p as __pageData,b as default};
